/* Calculateur de VaR paramétrique + Expected Shortfall */
(function () {
  var TD = 252; // jours de trading par an

  // Inverse de la loi normale standard (Acklam, 2003)
  function invNorm(p) {
    var a=[-3.969683028665376e+01,2.209460984245205e+02,-2.759285104469687e+02,1.383577518672690e+02,-3.066479806614716e+01,2.506628277459239e+00];
    var b=[-5.447609879822406e+01,1.615858368580409e+02,-1.556989798598866e+02,6.680131188771972e+01,-1.328068155288572e+01];
    var c=[-7.784894002430293e-03,-3.223964580411365e-01,-2.400758277161838e+00,-2.549732539343734e+00,4.374664141464968e+00,2.938163982698783e+00];
    var d=[7.784695709041462e-03,3.224671290700398e-01,2.445134137142996e+00,3.754408661907416e+00];
    var pl=0.02425, ph=1-pl, q, r;
    if (p<pl){ q=Math.sqrt(-2*Math.log(p)); return (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1); }
    if (p<=ph){ q=p-0.5; r=q*q; return (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q/(((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1); }
    q=Math.sqrt(-2*Math.log(1-p)); return -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1);
  }
  function normPdf(z){ return Math.exp(-z*z/2)/Math.sqrt(2*Math.PI); }

  function lang(){ return document.body.getAttribute("data-active-lang") || "fr"; }
  function locale(){ var l=lang(); return l==="en" ? "en-US" : (l==="nl" ? "nl-BE" : "fr-FR"); }

  function fmtMoney(x){
    return new Intl.NumberFormat(locale(), {style:"currency", currency:"EUR", maximumFractionDigits:0}).format(x);
  }
  function fmtPct(x){ return (x*100).toFixed(2).replace(".", lang()==="en" ? "." : ",") + "%"; }
  function ofPortfolio(){
    var l=lang();
    if (l==="en") return " of portfolio";
    if (l==="nl") return " van portefeuille";
    return " du portefeuille";
  }
  function horizonLabel(){
    var l=lang();
    if (l==="en") return "σ over horizon = ";
    if (l==="nl") return "σ over horizon = ";
    return "σ sur horizon = ";
  }

  function $(id){ return document.getElementById(id); }

  function compute(){
    var V   = parseFloat($("v-value").value) || 0;
    var vol = parseFloat($("v-vol").value)/100;
    var mu  = parseFloat($("v-mu").value)/100;
    var h   = parseInt($("v-h").value,10);
    var c   = parseFloat($("v-c").value)/100;

    $("v-vol-out").textContent = $("v-vol").value + "%";
    $("v-mu-out").textContent  = $("v-mu").value + "%";
    $("v-h-out").textContent   = h;
    $("v-c-out").textContent   = $("v-c").value + "%";

    var z    = invNorm(c);
    var sigH = vol * Math.sqrt(h/TD);
    var muH  = mu * (h/TD);

    var varRatio = z*sigH - muH;
    if (varRatio < 0) varRatio = 0;
    var varAbs = V * varRatio;

    var esRatio = sigH * normPdf(z)/(1-c) - muH;
    if (esRatio < 0) esRatio = 0;
    var esAbs = V * esRatio;

    $("r-var").textContent     = fmtMoney(varAbs);
    $("r-var-pct").textContent = fmtPct(varRatio) + ofPortfolio();
    $("r-es").textContent      = fmtMoney(esAbs);
    $("r-es-pct").textContent  = fmtPct(esRatio) + ofPortfolio();
    $("r-detail").textContent  = "z = " + z.toFixed(3) + "  ·  " + horizonLabel() + (sigH*100).toFixed(3) + "%";
  }

  ["v-value","v-vol","v-mu","v-h","v-c"].forEach(function(id){
    var el = document.getElementById(id);
    if (el){ el.addEventListener("input", compute); }
  });
  document.querySelectorAll(".lang-toggle button").forEach(function(b){
    b.addEventListener("click", function(){ setTimeout(compute, 0); });
  });
  document.addEventListener("DOMContentLoaded", compute);
  compute();
})();
